const number1 = document.getElementById("number1")
const number2 = document.getElementById("number2")
const number3 = document.getElementById("number3")
const number4 = document.getElementById("number4")
const number5 = document.getElementById("number5")
const powerball = document.getElementById("powerball")
const powerplay = document.getElementById("powerplay")

const submitBtn = document.getElementById("submit-btn")
const mainResult = document.getElementById("main-result")
const numbersDisplay = document.getElementById("numbers-display")
const tableResult = document.getElementById("table")


const calcWin = (play, result) => {

    let playWhite = play.slice(0, 5)
    let playPower = Number(play[5])
    resultNums = [Number(result["Ball 1"]), Number(result["Ball 2"]), Number(result["Ball 3"]), Number(result["Ball 4"]), Number(result["Ball 5"]), Number(result["Powerball"])]
    let resultWhite = resultNums.slice(0, 5)
    let resultPower = Number(resultNums[5])
    let whiteMatches = 0
    let totalWin = 0

    for (let i = 0; i < resultWhite.length; i++) {
        if (playWhite.includes(resultWhite[i])) {
            whiteMatches += 1
        }
    }

    if (resultPower === playPower) {
        totalWin = 1
    }

    if (resultPower === playPower && whiteMatches === 2 || whiteMatches === 3) {
        totalWin = 2
    }

    if (resultPower === playPower && whiteMatches === 3 || whiteMatches === 4) {
        totalWin = 3
    }

    if (resultPower === playPower && whiteMatches === 4) {
        totalWin = 4
    }

    if (whiteMatches === 5) {
        totalWin = 5
    }

    if (resultPower === playPower && whiteMatches === 5) {
        totalWin = 6
    }

    return totalWin
}

const winAmount = win => {
    let biggestWin = winChart[win[2]]

    if (biggestWin <= 50000 && play[1]) {
        biggestWin *= win[1]
    }

    if (biggestWin > 50000 && play[1]) {
        biggestWin *= 2
    }

    if (biggestWin > 3000000 && play[1]) {
        biggestWin = Number(win[3])
    }

    return biggestWin
}

const findBigWin = data => {

    let wins = []

    for (let i = 0; i < data.length; i++) {
        let win = calcWin(play[0], data[i])
        let mult = play[1] ? Number(data[i]["Power Play"]) : 0
        if (data[i]["SubName"] === "") {
            wins.push([data[i]["Date"], mult, win, data[i]["Jackpot"]])
        }
    }

    wins.sort((a, b) => b[1] - a[1])
    wins.sort((a, b) => b[2] - a[2])

    
    let topWin = winAmount(wins[0])

    numbersDisplay.innerHTML = `Your Numbers: ${number1.value} ${number2.value} ${number3.value} ${number4.value} ${number5.value} <span style="color: red">${powerball.value}</span>`

    mainResult.innerHTML = `Your biggest win would have happened on ${wins[0][0]}. You would have won $${topWin.toLocaleString()}`

    let table = `<table border="1">
                    <thead>
                        <tr>
                            <th>Date</th>
                            <th>Win Amount</th>
                        </tr>
                    </thead>
                    <tbody>`
    
    let topTen = wins.slice(1, 11)

    for (let i = 0; i < topTen.length; i++) {
        table += `<tr>
                    <td>${topTen[i][0]}</td>
                    <td>$${winAmount(topTen[i]).toLocaleString()}</td>
                  </tr>`
    }
        
    table += `</tbody></table>`;

    tableResult.innerHTML = table
}


